import { loadFont } from "@remotion/google-fonts/Saira";
import React from "react";
import { AbsoluteFill, Easing, Img, interpolate, staticFile, useCurrentFrame } from "remotion";
import { Cena5, Cena6, Cena9, Flood, Fundo, LogoAbre, RV_FPS, RV_FRAMES, Scene, Slash } from "./Rival";
import { Cena, Mosaico } from "./RivalV5";
import { A, DUR, LEAD } from "./tempos";

// RIVAL (cliente caio rivalx) — v7: roteiro de 9 cenas do cliente (voz e tempos da v4), pedido sobre a v6:
// "mais dinamicidade nos primeiros 5 segundos e mostrar mais o site".
// 1) Abertura refeita: cada dor do roteiro bate na tela em letra gigante, com virada de cor a cada batida.
// 2) Mais site: três telas sobem embaixo do logo; taxas e saques na carteira; assinatura no Rival Club; premiação na
//    sala e no extrato; os quatro diferenciais do encerramento sobre telas reais.
// Da v4 ficam só: o logo, a interface genérica lenta (cena 5), os cadeados (cena 6) e o final.
export const V7_FPS = RV_FPS;
export const V7_FRAMES = RV_FRAMES;

const { fontFamily: F } = loadFont("normal", { weights: ["900"], subsets: ["latin", "latin-ext"] });
const RED = "#FF2A3F", DRED = "#991926", TEAL = "#009982", GOLD = "#DCB859", WHITE = "#F4F4F5", BG = "#07080A";
const BEAT = 60 / 140;
const cl = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;
const OUT = Easing.bezier(0.16, 1, 0.3, 1);
const k = (t: number, a: number, d = 0.45) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: OUT });
const lin = (t: number, a: number, b: number) => interpolate(t, [a, b], [0, 1], cl);
const acc = (t: number, a: number, b: number) => interpolate(t, [a, b], [0, 1], { ...cl, easing: Easing.bezier(0.55, 0, 1, 0.45) });
const slam = (t: number, at: number) => interpolate(t, [at, at + 0.22], [0, 1], { ...cl, easing: Easing.out(Easing.back(2.2)) });

// ───────── abertura (0–4,9 s): uma dor por batida, letra gigante, cor que vira ─────────
type Bt = { a: number; bg: string; fg: string; ox: number; oy: number; lines: { w: string; at: number; cap: number; hl?: string }[]; extra?: "pct" | "risco" | "barras" };
const BATIDAS: Bt[] = [
  { a: -LEAD, bg: BG, fg: WHITE, ox: 540, oy: 960, lines: [{ w: "Cansado", at: A.cansado, cap: 180 }, { w: "de plataformas", at: A.plataformas1 - 0.12, cap: 96, hl: RED }] },
  { a: A.taxas - 0.1, bg: RED, fg: WHITE, ox: 0, oy: 1920, lines: [{ w: "Taxas", at: A.taxas - 0.05, cap: 240 }, { w: "altas", at: A.taxas + 0.3, cap: 240 }], extra: "pct" },
  { a: A.vantagens - 0.1, bg: WHITE, fg: BG, ox: 1080, oy: 0, lines: [{ w: "Poucas", at: A.vantagens - 0.05, cap: 200 }, { w: "vantagens", at: A.vantagens + 0.3, cap: 150 }], extra: "risco" },
  { a: A.limitacoes - 0.1, bg: DRED, fg: WHITE, ox: 0, oy: 0, lines: [{ w: "Limitações", at: A.limitacoes - 0.05, cap: 140 }], extra: "barras" },
  { a: A.competir - 0.1, bg: BG, fg: WHITE, ox: 1080, oy: 1920, lines: [{ w: "para", at: A.competir - 0.08, cap: 200 }, { w: "competir?", at: A.competir + 0.12, cap: 150, hl: RED }] },
];
const Abre7: React.FC<{ t: number; b: number }> = ({ t, b }) => {
  if (t >= b) return null;
  const idx = BATIDAS.reduce((s, x, i) => (t >= x.a ? i : s), 0);
  const sai = acc(t, b - 0.3, b);
  return (
    <AbsoluteFill style={{ transform: `scale(${(1 + 0.7 * sai).toFixed(4)})`, filter: sai > 0.02 ? `blur(${(sai * 16).toFixed(1)}px)` : undefined }}>
      {BATIDAS.map((x, i) => {
        if (i < idx - 1 || i > idx) return null;
        const fim = BATIDAS[i + 1]?.a ?? b;
        const r = i === 0 ? 3000 : 2400 * k(t, x.a, 0.3);
        const tremor = x.lines.reduce((s, l) => s + (t >= l.at ? 16 * Math.exp(-(t - l.at) * 13) * Math.sin((t - l.at) * 95) : 0), 0);
        return (
          <AbsoluteFill key={i} style={{ background: x.bg, clipPath: `circle(${r.toFixed(1)}px at ${x.ox}px ${x.oy}px)`, overflow: "hidden" }}>
            {/* faixa diagonal correndo: a cena nunca fica parada */}
            <div style={{ position: "absolute", left: -700 + 2400 * lin(t, x.a, fim + 0.3), top: -400, width: 280, height: 2800, background: x.bg === WHITE ? "rgba(0,0,0,0.07)" : "rgba(255,255,255,0.06)", transform: "rotate(22deg)" }} />
            {/* a palavra da batida repetida em letra-fantasma, correndo em cima e embaixo: preenche o quadro */}
            {[0, 1].map((j) => (
              <div key={`m${j}`} style={{ position: "absolute", left: -1400, top: j ? 1420 : 250, width: 5000, fontFamily: F, fontWeight: 900, fontSize: 230, lineHeight: 1, textTransform: "uppercase", whiteSpace: "nowrap", color: "transparent", WebkitTextStroke: `3px ${x.bg === WHITE ? "rgba(0,0,0,0.22)" : "rgba(255,255,255,0.22)"}`, transform: `translateX(${((j ? -1 : 1) * (-300 + 520 * (t - x.a))).toFixed(1)}px)` }}>
                {Array.from({ length: 8 }).map(() => x.lines[x.lines.length - 1].w.replace("?", "")).join(" · ")}
              </div>
            ))}
            {x.extra === "pct" && [0, 1, 2].map((j) => (
              <div key={j} style={{ position: "absolute", left: [40, 640, 330][j], top: [1500, 1250, 300][j] - 420 * lin(t, x.a, fim), fontFamily: F, fontWeight: 900, fontSize: [520, 420, 360][j], lineHeight: 1, color: "rgba(0,0,0,0.16)", transform: `rotate(${[-12, 10, -6][j]}deg)` }}>%</div>
            ))}
            {x.extra === "barras" && (
              <>
                <div style={{ position: "absolute", left: 0, right: 0, top: 0, height: 560 * k(t, x.a + 0.1, 0.6), background: "#000" }} />
                <div style={{ position: "absolute", left: 0, right: 0, bottom: 0, height: 560 * k(t, x.a + 0.1, 0.6), background: "#000" }} />
              </>
            )}
            <div style={{ position: "absolute", left: 100, right: 100, top: 560, height: 800, display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", transform: `translate(${tremor.toFixed(1)}px, ${(-tremor * 0.6).toFixed(1)}px) scale(${(1 + 0.07 * lin(t, x.a, fim)).toFixed(4)})` }}>
              {x.lines.map((l, j) => {
                const e = slam(t, l.at);
                const fs = Math.min(l.cap, Math.floor(840 / (0.66 * l.w.length + (l.hl ? 0.7 : 0))));
                return (
                  <div key={j} style={{ position: "relative", fontFamily: F, fontWeight: 900, fontSize: fs, lineHeight: 1.06, textTransform: "uppercase", whiteSpace: "nowrap", color: x.fg, opacity: t >= l.at ? Math.min(1, e * 3) : 0, transform: `scale(${(1.9 - 0.9 * e).toFixed(4)}) rotate(${((1 - e) * (j % 2 ? 5 : -5)).toFixed(2)}deg)`, filter: e < 0.95 ? `blur(${((1 - e) * 16).toFixed(1)}px)` : undefined, padding: "0 0.2em" }}>
                    {l.hl && <div style={{ position: "absolute", left: 0, right: 0, top: "7%", bottom: "5%", background: l.hl, transform: "skewX(-9deg)" }} />}
                    <span style={{ position: "relative" }}>{l.w}</span>
                    {x.extra === "risco" && j === 1 && <div style={{ position: "absolute", left: "-3%", right: "-3%", top: "46%", height: 20, background: RED, transform: `rotate(-3deg) scaleX(${k(t, l.at + 0.28, 0.3).toFixed(4)})`, transformOrigin: "left center" }} />}
                  </div>
                );
              })}
            </div>
          </AbsoluteFill>
        );
      })}
    </AbsoluteFill>
  );
};

// três telas do site sobem embaixo do logo ("Conheça a Rival")
const Trio: React.FC<{ t: number; a: number; b: number }> = ({ t, a, b }) => {
  if (t < a || t >= b) return null;
  const sai = acc(t, b - 0.3, b);
  return (
    <>
      {["sala-1-topo", "hub-1-topo", "tabela-2-classificacao"].map((src, i) => {
        const e = interpolate(t, [a + 0.75 + [0.1, 0, 0.2][i], a + 1.3 + [0.1, 0, 0.2][i]], [0, 1], { ...cl, easing: Easing.out(Easing.back(1.3)) });
        return (
          <div key={i} style={{ position: "absolute", left: [40, 370, 700][i], top: [1400, 1340, 1400][i], width: 340, height: 620, borderRadius: 28, overflow: "hidden", border: "2px solid rgba(255,255,255,0.2)", boxShadow: "0 0 0 5px rgba(255,42,63,0.2), 0 30px 80px rgba(0,0,0,0.7)", transform: `translateY(${((1 - e) * 760 + sai * 500 - 26 * lin(t, a + 1.3, b)).toFixed(1)}px) rotate(${[-5, 0, 5][i]}deg)`, opacity: 1 - sai }}>
            <Img src={staticFile(`caio-rivalx/site/${src}.jpg`)} style={{ width: 340, display: "block" }} />
          </div>
        );
      })}
    </>
  );
};

export const RivalV7: React.FC = () => {
  const frame = useCurrentFrame();
  const t = frame / V7_FPS - LEAD;
  const tv = frame / V7_FPS;
  const ph = (tv % BEAT) / BEAT;
  const pulse = tv > 0.4 ? Math.exp(-ph * 9) : 0;
  const c2 = A.taxaSaque - 0.35, cFim = A.esses - 0.1, c3 = A.assinatura - 0.1, c4 = A.alem - 0.1, c5 = A.eNada - 0.1, c5b = A.aRival, c6 = A.semRegras - 0.1, c6b = A.naRival;
  const c7 = A.jogue - 0.1, c8 = A.eTudo - 0.1, cMos = A.amigos + 1.45, c9 = A.menosTaxas - 0.08;
  return (
    <AbsoluteFill style={{ background: "#07080A", overflow: "hidden" }}>
      <Fundo tv={tv} />
      <AbsoluteFill style={{ transform: `scale(${1 + 0.012 * pulse})` }}>
        <Abre7 t={t} b={A.conheca} />
        <Scene t={t} a={A.conheca} b={c2} cam="pull" exit="zoom"><LogoAbre t={t} /></Scene>
        <Trio t={t} a={A.conheca} b={c2} />

        {/* cena 2: taxas e saques, na carteira de verdade (os números ficam no letreiro, como o cliente escreveu) */}
        <Cena t={t} a={c2} b={c3} size={140}
          shots={[
            { src: "carteira-1-saldo", at: c2, kf: [[c2, 400, 476, 1.05], [A.ate - 0.2, 400, 476, 1.05], [A.ate + 0.3, 560, 440, 1.5], [A.depositos - 0.25, 560, 440, 1.5], [A.depositos + 0.2, 240, 440, 1.5]], marks: [{ kind: "tap", x: 590, y: 411, at: A.sete + 0.1 }, { kind: "tap", x: 210, y: 411, at: A.depositos + 0.55 }] },
            { src: "carteira-2-movimentacoes", at: A.saques2 - 0.1, enter: "up", kf: [[A.saques2 - 0.1, 400, 560, 1.05], [A.saques2 + 0.5, 400, 640, 1.2]], marks: [{ kind: "box", x: 62, y: 636, w: 676, h: 98, at: A.saques2 + 0.45, c: RED }] },
            { src: "carteira-1-saldo", at: A.maisPrat - 0.1, enter: "right", kf: [[A.maisPrat - 0.1, 400, 476, 1.05], [c3, 400, 940, 1.08]] },
          ]}
          tits={[{ at: A.taxaSaque, lines: [{ w: "Taxa de saque" }] }, { at: A.ate, lines: [{ w: "Até 7%", hl: RED }, { w: "taxa de saque" }] }, { at: A.depositos - 0.1, lines: [{ w: "0%", hl: TEAL }, { w: "no depósito" }] }, { at: A.saques2 - 0.1, lines: [{ w: "Saque em" }, { w: "até 24h", hl: RED }] }, { at: A.maisPrat, lines: [{ w: "Mais" }, { w: "praticidade", hl: TEAL }] }]} />

        {/* cena 3: assinatura (Rival Club, sem descer até os preços) e premiação (sala e extrato) */}
        <Cena t={t} a={c3} b={c4}
          shots={[
            { src: "club-2-beneficios", at: c3, kf: [[c3, 400, 476, 1.05], [A.barata, 400, 545, 1.2]], marks: [{ kind: "box", x: 80, y: 190, w: 270, h: 60, at: A.barata, c: GOLD }] },
            { src: "hub-3-fila-salas", at: A.distribuicao - 0.1, enter: "up", kf: [[A.distribuicao - 0.1, 400, 984, 1.05], [A.premiacoes1 - 0.3, 400, 984, 1.05], [A.premiacoes1 + 0.2, 400, 1040, 1.22]], marks: [{ kind: "box", x: 406, y: 1158, w: 328, h: 96, at: A.premiacoes1 + 0.15, c: GOLD }] },
            { src: "carteira-2-movimentacoes", at: A.porque - 0.1, enter: "right", kf: [[A.porque - 0.1, 400, 560, 1.05], [A.merece, 400, 540, 1.2]], marks: [{ kind: "box", x: 62, y: 428, w: 676, h: 96, at: A.merece, c: GOLD }] },
          ]}
          tits={[{ at: A.assinatura, lines: [{ w: "Assinatura" }, { w: "mais acessível", hl: TEAL }] }, { at: A.distribuicao, lines: [{ w: "Mais premiação" }, { w: "para players", hl: RED }] }, { at: A.porque, lines: [{ w: "Quem vence merece" }, { w: "ser valorizado", hl: GOLD }] }]} />

        {/* cena 4: campeonatos semanais, ranking e premiações */}
        <Cena t={t} a={c4} b={c5}
          shots={[
            { src: "hub-3-fila-salas", at: c4, kf: [[c4, 400, 984, 1.05], [A.campeonatos - 0.1, 400, 1020, 1.12]] },
            { src: "torneios-1-lista", at: A.campeonatos - 0.1, enter: "right", kf: [[A.campeonatos - 0.1, 400, 476, 1.05], [A.campeonatos + 0.6, 400, 760, 1.1]] },
            { src: "torneio-3-chave", at: A.campeonatos + 0.6, enter: "up", kf: [[A.campeonatos + 0.6, 400, 476, 1.05], [A.disputa - 0.1, 400, 760, 1.05]] },
            { src: "tabela-2-classificacao", at: A.disputa - 0.1, enter: "right", kf: [[A.disputa - 0.1, 400, 476, 1.05], [A.premiacoes2 - 0.1, 400, 940, 1.05]] },
            { src: "tabela-1-premios", at: A.premiacoes2 - 0.1, enter: "up", kf: [[A.premiacoes2 - 0.1, 400, 984, 1.05], [A.premiacoes2 + 0.5, 330, 1105, 1.38]], marks: [{ kind: "box", x: 58, y: 1062, w: 330, h: 158, at: A.premiacoes2 + 0.4, c: GOLD }] },
            { src: "hub-4-comunidade-criador", at: A.comunidades1 - 0.15, enter: "right", kf: [[A.comunidades1 - 0.15, 400, 476, 1.05], [c5, 400, 470, 1.12]], marks: [{ kind: "box", x: 28, y: 308, w: 744, h: 450, at: A.comunidades1 + 0.15, c: GOLD }] },
          ]}
          tits={[{ at: A.alem, lines: [{ w: "Além dos" }, { w: "lobbies", hl: RED }] }, { at: A.campeonatos, lines: [{ w: "Campeonatos" }, { w: "semanais", hl: RED }] }, { at: A.disputa, lines: [{ w: "Rankings" }, { w: "premiados", hl: GOLD }] }, { at: A.premiacoes2, lines: [{ w: "Premiações" }, { w: "da Rival", hl: GOLD }] }, { at: A.comunidades1, lines: [{ w: "E das" }, { w: "comunidades", hl: GOLD }] }]} />

        {/* cena 5: a interface genérica lenta (v4) e, depois da lâmina, a plataforma de verdade navegando rápido */}
        <Scene t={t} a={c5} b={c5b} cam="rot" enter="up"><Cena5 t={t} /></Scene>
        <Cena t={t} a={c5b} b={c6}
          shots={[
            { src: "hub-1-topo", at: c5b, kf: [[c5b, 400, 476, 1.05], [c5b + 1.0, 400, 760, 1.05]] },
            { src: "torneios-1-lista", at: c5b + 1.05, enter: "right", kf: [[c5b + 1.05, 400, 476, 1.05], [c5b + 2.0, 400, 700, 1.05]] },
            { src: "tabela-2-classificacao", at: c5b + 2.0, enter: "right", kf: [[c5b + 2.0, 400, 476, 1.05], [A.rapida - 0.1, 400, 760, 1.05]] },
            { src: "comunidades-1-lista", at: A.rapida - 0.1, enter: "up", kf: [[A.rapida - 0.1, 400, 476, 1.05], [A.leve - 0.1, 400, 800, 1.05]] },
            { src: "times-1", at: A.leve - 0.1, enter: "right", kf: [[A.leve - 0.1, 400, 476, 1.05], [A.leve + 0.9, 400, 760, 1.05]] },
            { src: "carteira-1-saldo", at: A.leve + 0.9, enter: "right", kf: [[A.leve + 0.9, 400, 476, 1.05], [A.leve + 1.9, 400, 700, 1.05]] },
            { src: "hub-2-aovivo-classificacao", at: A.leve + 1.9, enter: "up", kf: [[A.leve + 1.9, 400, 476, 1.05], [A.maisTempo - 0.1, 400, 900, 1.05]] },
            { src: "sala-1-topo", at: A.maisTempo - 0.1, enter: "zoom", kf: [[A.maisTempo - 0.1, 400, 476, 1.08], [c6, 380, 540, 1.25]] },
          ]}
          tits={[{ at: c5b + 0.1, lines: [{ w: "Mais" }, { w: "velocidade", hl: RED }] }, { at: A.rapida, lines: [{ w: "Menos" }, { w: "travamentos", hl: RED }] }, { at: A.leve, lines: [{ w: "Plataforma leve" }, { w: "e otimizada", hl: TEAL }] }, { at: A.maisTempo, lines: [{ w: "Mais tempo" }, { w: "competindo", hl: RED }] }]} />

        {/* cena 6: os cadeados (v4) e, no "Na Rival", a sala 5v5 de verdade */}
        <Scene t={t} a={c6} b={c6b} cam="pull"><Cena6 t={t} /></Scene>
        <Cena t={t} a={c6b} b={c7}
          shots={[
            { src: "sala-1-topo", at: c6b, kf: [[c6b, 400, 476, 1.05], [A.liberdade - 0.1, 380, 540, 1.2]], marks: [{ kind: "box", x: 60, y: 432, w: 680, h: 120, at: c6b + 0.5, c: RED }] },
            { src: "sala-2-vagas", at: A.liberdade - 0.1, enter: "up", kf: [[A.liberdade - 0.1, 400, 476, 1.05], [A.desafiar + 1.6, 400, 984, 1.05]] },
            { src: "sala-1-topo", at: A.desafiar + 1.7, enter: "zoom", kf: [[A.desafiar + 1.7, 370, 560, 1.3], [c7, 370, 575, 1.4]], marks: [{ kind: "box", x: 68, y: 632, w: 346, h: 48, at: A.desafiar + 2.1, c: GOLD }] },
          ]}
          tits={[{ at: c6b + 0.1, lines: [{ w: "Na Rival," }, { w: "partida 5v5", hl: RED }] }, { at: A.liberdade, lines: [{ w: "Mais liberdade" }, { w: "para competir", hl: RED }] }]} />

        {/* cena 7: streamers e criadores */}
        <Cena t={t} a={c7} b={c8}
          shots={[
            { src: "hub-2-aovivo-classificacao", at: c7, kf: [[c7, 400, 476, 1.05], [A.streamers, 400, 420, 1.15]], marks: [{ kind: "box", x: 50, y: 108, w: 700, h: 286, at: A.streamers, c: RED }] },
            { src: "jogador-1-kaori", at: A.streamers + 1.3, enter: "right", kf: [[A.streamers + 1.3, 400, 476, 1.05], [A.streamers + 2.0, 330, 560, 1.32]], marks: [{ kind: "box", x: 28, y: 654, w: 180, h: 48, at: A.streamers + 2.0, c: GOLD }] },
            { src: "hub-4-comunidade-criador", at: A.criadores - 0.3, enter: "up", kf: [[A.criadores - 0.3, 400, 984, 1.05], [A.criadores + 0.4, 400, 1030, 1.18]], marks: [{ kind: "box", x: 30, y: 962, w: 740, h: 224, at: A.criadores + 0.3, c: GOLD }] },
            { src: "sala-2-vagas", at: A.experiencia - 0.15, enter: "right", kf: [[A.experiencia - 0.15, 400, 476, 1.05], [c8, 400, 900, 1.05]] },
          ]}
          tits={[{ at: A.jogue, lines: [{ w: "Jogue com seus" }, { w: "streamers", hl: RED }] }, { at: A.criadores - 0.2, lines: [{ w: "Seus criadores" }, { w: "favoritos", hl: GOLD }] }, { at: A.experiencia, lines: [{ w: "A experiência" }, { w: "de perto", hl: RED }] }]} />

        {/* cena 8: tudo em um só lugar */}
        <Cena t={t} a={c8} b={cMos}
          shots={[
            { src: "hub-1-topo", at: c8, kf: [[c8, 400, 476, 1.05], [A.comunidades2 - 0.1, 400, 700, 1.05]] },
            { src: "comunidades-1-lista", at: A.comunidades2 - 0.1, enter: "right", kf: [[A.comunidades2 - 0.1, 400, 500, 1.05], [A.suporte - 0.1, 400, 760, 1.05]] },
            { src: "suporte-1", at: A.suporte - 0.1, enter: "right", kf: [[A.suporte - 0.1, 400, 476, 1.05], [A.chat - 0.1, 400, 760, 1.08]], marks: [{ kind: "box", x: 30, y: 820, w: 740, h: 294, at: A.suporte + 0.35, c: TEAL }] },
            { src: "chat-1-conversas", at: A.chat - 0.1, enter: "up", kf: [[A.chat - 0.1, 400, 476, 1.05], [A.amigos - 0.1, 400, 480, 1.12]] },
            { src: "amigos-1", at: A.amigos - 0.1, enter: "right", kf: [[A.amigos - 0.1, 400, 600, 1.05], [cMos, 400, 880, 1.08]] },
          ]}
          tits={[{ at: A.eTudo, lines: [{ w: "Tudo em uma" }, { w: "plataforma", hl: RED }] }, { at: A.comunidades2, lines: [{ w: "Comunidades", hl: RED }] }, { at: A.suporte, lines: [{ w: "Suporte" }, { w: "integrado", hl: TEAL }] }, { at: A.chat, lines: [{ w: "Chat" }, { w: "privado", hl: TEAL }] }, { at: A.amigos, lines: [{ w: "Lista de" }, { w: "amigos", hl: TEAL }] }]} />
