import { loadFont } from "@remotion/google-fonts/Saira";
import React from "react";
import { AbsoluteFill, Easing, Img, OffthreadVideo, Sequence, interpolate, staticFile, useCurrentFrame } from "remotion";
import { A, DUR, LEAD } from "./tempos";

// RIVAL (cliente caio rivalx). Motion 01: os diferenciais da plataforma, sem citar concorrente.
// Roteiro de 9 cenas mandado pelo cliente; voz o locutor (src/voz-v1.wav). Jeito: motion (só chegaram logos).
// Identidade: fundo preto do logo, branco #F4F4F5, vermelho #FF2A3F (destaque), vermelho escuro #991926, teal #009982,
// dourado #DCB859 (dinheiro, prêmio), cinza #9A9FA8. Letra larga e pesada como o logo (Saira).
// Elemento-fio: a lâmina vermelha (o traço do X do logo) corta a tela nas trocas de cena.
// As telas da plataforma são desenhadas e ilustrativas (o cliente não mandou prints): sem nomes, valores ou dados inventados.
// Tempos = tempos da locução (t = 0 é o começo da voz; o vídeo tem LEAD de entrada).
// v2 (correção da Nina): todo texto dentro da área segura (x 120–960, y 250–1480); conteúdo numa coluna de 800 px
// (x 140–940); títulos de 110–150 px quebrados em linhas; câmera com pouca escala para nada sair da área segura.

const { fontFamily: F } = loadFont("normal", { weights: ["500", "600", "700", "800", "900"], subsets: ["latin", "latin-ext"] });

export const RV_FPS = 30;
export const RV_FRAMES = Math.round(DUR * RV_FPS);

const cl = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;
const OUT = Easing.bezier(0.16, 1, 0.3, 1);
const BACK = Easing.out(Easing.back(1.5));
const INOUT = Easing.bezier(0.65, 0, 0.35, 1);
const IN = Easing.bezier(0.55, 0, 1, 0.45);
const k = (t: number, a: number, d = 0.45) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: OUT });
const pop = (t: number, a: number, d = 0.42) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: BACK });
const lin = (t: number, a: number, b: number) => interpolate(t, [a, b], [0, 1], cl);
const io = (t: number, a: number, b: number) => interpolate(t, [a, b], [0, 1], { ...cl, easing: INOUT });
const acc = (t: number, a: number, b: number) => interpolate(t, [a, b], [0, 1], { ...cl, easing: IN });
const bump = (t: number, a: number, d = 0.4) => (t < a || t > a + d ? 0 : Math.sin(((t - a) / d) * Math.PI) * (1 - (t - a) / d));

const BG = "#07080A";
const PANEL = "#121419";
const PANEL2 = "#191C22";
const LINE = "#262A32";
const WHITE = "#F4F4F5";
const RED = "#FF2A3F";
const DRED = "#991926";
const TEAL = "#009982";
const GOLD = "#DCB859";
const GRAY = "#9A9FA8";
const img = (f: string) => staticFile(`caio-rivalx/${f}`);

// ───────── texto ─────────
// palavra que sobe da linha (máscara); entra e fica parada; sai no mesmo lugar
const Rise: React.FC<{ t: number; at: number; out?: number; children: React.ReactNode }> = ({ t, at, out, children }) => {
  // v3: a palavra bate na tela (vem grande e desfocada, assenta com mola curta) e fica parada
  const e = interpolate(t, [at, at + 0.26], [0, 1], { ...cl, easing: Easing.out(Easing.back(1.5)) });
  const f = k(t, at, 0.2);
  const o = out === undefined ? 0 : acc(t, out, out + 0.18);
  return (
    <div style={{ transform: `translateY(${((1 - e) * 35).toFixed(2)}%) scale(${(0.55 + 0.45 * e).toFixed(4)}) rotate(${((1 - e) * -5).toFixed(2)}deg) translateX(${(-o * 400).toFixed(1)}px)`, opacity: Math.min(1, f * 2) * (1 - o), filter: (1 - f) * 12 + o * 10 > 0.3 ? `blur(${((1 - f) * 12 + o * 10).toFixed(1)}px)` : undefined }}>{children}</div>
  );
};

type Ln = { w: string; at: number; hl?: string; c?: string };
// largura máxima de uma linha de título: o corpo diminui só se a linha não couber em 800 px (Saira 900 ≈ 0,66 em por letra)
const MAXW = 780;
const fit = (w: string, size: number, hl?: boolean) => Math.min(size, Math.floor(MAXW / (0.66 * w.length + (hl ? 0.7 : 0))));
// título centralizado, uma linha por item; destaque numa faixa chapada inclinada
const Title: React.FC<{ t: number; lines: Ln[]; size: number; top: number; out?: number }> = ({ t, lines, size, top, out }) => (
  <div style={{ position: "absolute", left: 140, right: 140, top, display: "flex", flexDirection: "column", alignItems: "center", gap: size * 0.1 }}>
    {lines.map((l, i) => {
      const sz = fit(l.w, size, !!l.hl);
      return (
      <Rise key={i} t={t} at={l.at} out={out}>
        <div
          style={{
            fontFamily: F, fontWeight: 900, fontSize: sz, lineHeight: 1.04, letterSpacing: "-0.01em", whiteSpace: "nowrap", textTransform: "uppercase",
            color: l.hl ? (l.hl === GOLD ? BG : WHITE) : l.c ?? WHITE,
            ...(l.hl ? { background: l.hl, padding: `${sz * 0.03}px ${sz * 0.26}px ${sz * 0.07}px`, transform: "skewX(-10deg)" } : {}),
          }}
        >
          <div style={l.hl ? { transform: "skewX(10deg)" } : undefined}>{l.w}</div>
        </div>
      </Rise>
      );
    })}
  </div>
);

