// ───────── câmera e transições ─────────
// cada cena entra já em movimento e sai acelerando; o tipo de câmera muda por cena
type Cam = "push" | "pull" | "panL" | "panR" | "tilt" | "rot";
type Mv = "zoom" | "up" | "left" | "none";
export const Scene: React.FC<{ t: number; a: number; b: number; cam: Cam; enter?: Mv; exit?: Mv; children: React.ReactNode }> = ({ t, a, b, cam, enter = "none", exit = "none", children }) => {
  if (t < a - 0.02 || t >= b) return null;
  const p = lin(t, a, b);
  let tf = "";
  if (cam === "push") tf = `scale(${1 + 0.03 * p})`;
  if (cam === "pull") tf = `scale(${1.03 - 0.03 * p})`;
  if (cam === "panL") tf = `translateX(${12 - 24 * p}px)`;
  if (cam === "panR") tf = `translateX(${-12 + 24 * p}px)`;
  if (cam === "tilt") tf = `translateY(${14 - 28 * p}px) scale(${1 + 0.02 * p})`;
  if (cam === "rot") tf = `rotate(${-0.8 + 1.6 * p}deg) scale(${1 + 0.02 * p})`;
  const ei = 1 - k(t, a, 0.5), eo = acc(t, b - 0.3, b);
  let et = "", blur = 0, op = 1;
  if (enter === "zoom") { et += ` scale(${1 + 0.35 * ei})`; blur += ei * 14; op *= 1 - ei * 0.6; }
  if (enter === "up") { et += ` translateY(${ei * 620}px)`; blur += ei * 10; }
  if (enter === "left") { et += ` translateX(${ei * 900}px)`; blur += ei * 10; }
  if (exit === "zoom") { et += ` scale(${1 + 1.6 * eo})`; blur += eo * 18; op *= 1 - eo * 0.9; }
  if (exit === "up") { et += ` translateY(${-eo * 1100}px)`; blur += eo * 12; }
  if (exit === "left") { et += ` translateX(${-eo * 1200}px)`; blur += eo * 12; }
  return (
    <AbsoluteFill style={{ transform: et || undefined, filter: blur > 0.3 ? `blur(${blur.toFixed(1)}px)` : undefined, opacity: op }}>
      <AbsoluteFill style={{ transform: tf }}>{children}</AbsoluteFill>
    </AbsoluteFill>
  );
};

// lâmina vermelha (o traço do X do logo) que corta a tela: a troca de cena acontece embaixo dela, em `at`
export const Slash: React.FC<{ t: number; at: number; dir?: 1 | -1 }> = ({ t, at, dir = 1 }) => {
  if (t < at - 0.3 || t > at + 0.3) return null;
  const p = interpolate(t, [at - 0.3, at + 0.3], [0, 1], { ...cl, easing: Easing.bezier(0.7, 0, 0.3, 1) });
  const x = (-3400 + 6800 * p) * dir;
  const band = (dx: number, c: string) => (
    <div style={{ position: "absolute", left: 540 - 1500 + x + dx, top: -1100, width: 3000, height: 4100, background: c, transform: `rotate(${dir * 22}deg)` }} />
  );
  return (
    <AbsoluteFill style={{ pointerEvents: "none", overflow: "hidden" }}>
      {band(-420 * dir, DRED)}
      {band(0, RED)}
    </AbsoluteFill>
  );
};

// inundação de cor: um círculo sai de (x, y), cobre a tela até `at` e abre um buraco que revela a cena seguinte
export const Flood: React.FC<{ t: number; at: number; x: number; y: number; c: string }> = ({ t, at, x, y, c }) => {
  if (t < at - 0.32 || t > at + 0.36) return null;
  const r1 = interpolate(t, [at - 0.32, at], [0, 2300], { ...cl, easing: IN });
  const r2 = interpolate(t, [at + 0.02, at + 0.36], [0, 2300], { ...cl, easing: OUT });
  const mask = `radial-gradient(circle at 540px 960px, transparent ${r2}px, #000 ${r2 + 1}px)`;
  return <AbsoluteFill style={{ pointerEvents: "none", background: c, clipPath: `circle(${r1}px at ${x}px ${y}px)`, WebkitMaskImage: mask, maskImage: mask }} />;
};

// troca rápida de lado: o bloco entra da direita e sai pela esquerda, com borrão de movimento
const whip = (t: number, a: number, b?: number): React.CSSProperties => {
  const i = 1 - k(t, a, 0.3), o = b === undefined ? 0 : acc(t, b - 0.05, b + 0.15);
  const bl = i * 18 + o * 18;
  return { transform: `translateX(${(i * 1000 - o * 1100).toFixed(1)}px) skewX(${(-i * 8 + o * 8).toFixed(2)}deg)`, filter: bl > 0.3 ? `blur(${bl.toFixed(1)}px)` : undefined };
};

// virada de fundo (inversão de cor): um círculo da cor sai de (x, y) e cobre o fundo em `a`; em `b` encolhe para o centro
const W_ = "#F4F4F5";
const Virada: React.FC<{ t: number; a: number; b?: number; c: string; x?: number; y?: number }> = ({ t, a, b, c, x = 540, y = 960 }) => {
  if (t < a - 0.01 || (b !== undefined && t > b + 0.25)) return null;
  const r = 2300 * k(t, a, 0.38) * (b === undefined ? 1 : 1 - acc(t, b - 0.05, b + 0.2));
  return <div style={{ position: "absolute", inset: -200, background: c, clipPath: `circle(${r}px at ${x + 200}px ${y + 200}px)` }} />;
};

