const Barreira: React.FC<{ t: number; at: number; ico: Ico; txt: string; side: 1 | -1; cut: number }> = ({ t, at, ico: I, txt, side, cut }) => {
  const e = pop(t, at, 0.4);
  const x = (1 - k(t, at, 0.45)) * 600 * side;
  const s = k(t, cut, 0.3);
  return (
    <div style={{ transform: `translateX(${x}px) scale(${0.88 + 0.12 * e})`, opacity: Math.min(1, e * 2), position: "relative" }}>
      <div style={{ width: 800, height: 230, background: PANEL, borderRadius: 30, border: `2px solid ${LINE}`, display: "flex", alignItems: "center", gap: 30, padding: "0 40px", boxSizing: "border-box", filter: `saturate(${1 - s * 0.8}) brightness(${1 - s * 0.45})` }}>
        <div style={{ width: 110, height: 110, borderRadius: 26, background: "rgba(255,42,63,0.13)", display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0 }}><I s={68} c={RED} w={2.2} /></div>
        <div style={{ fontFamily: F, fontWeight: 900, fontSize: 56, color: WHITE, textTransform: "uppercase", letterSpacing: "-0.01em", whiteSpace: "nowrap" }}>{txt}</div>
      </div>
      {/* risco vermelho quando a pergunta fecha */}
      <div style={{ position: "absolute", left: 24, top: 109, height: 12, width: 752 * s, background: RED, borderRadius: 12, transform: "rotate(-2deg)", transformOrigin: "left center" }} />
    </div>
  );
};

