// ───────── cena 2: taxas e saques ─────────
// número que rola como contador e para no valor
const Roll: React.FC<{ t: number; at: number; to: number; size: number; color: string }> = ({ t, at, to, size, color }) => {
  const v = to * k(t, at, 0.8);
  const lo = Math.floor(v), f = v - lo;
  const cell = (n: number, o: number) => <div style={{ position: "absolute", left: 0, right: 0, top: o * size * 1.05, textAlign: "center" }}>{n}</div>;
  return (
    <div style={{ position: "relative", height: size * 1.05, width: size * 0.62, overflow: "hidden", fontFamily: F, fontWeight: 900, fontSize: size, lineHeight: 1.05, color, fontVariantNumeric: "tabular-nums" }}>
      {cell(lo, -f)}{lo < to && cell(lo + 1, 1 - f)}
    </div>
  );
};

