const Transfer: React.FC<{ t: number; at: number }> = ({ t, at }) => {
  const e = k(t, at, 0.5);
  const fill = io(t, at + 0.45, A.saldo + 0.15);
  const done = pop(t, A.saldo + 0.2, 0.4);
  const coin = (i: number) => {
    const p = lin(t, at + 0.45 + i * 0.22, at + 1.05 + i * 0.22);
    return p > 0 && p < 1 ? (
      <div key={i} style={{ position: "absolute", left: 300 + 160 * p, top: 120 - Math.sin(p * Math.PI) * 150, width: 80, height: 80, borderRadius: 80, background: GOLD, opacity: Math.min(1, p * 5, (1 - p) * 5), boxShadow: "inset 0 -7px 0 rgba(0,0,0,0.22)" }} />
    ) : null;
  };
  const box = (right: boolean) => (
    <div style={{ position: "absolute", [right ? "right" : "left"]: 0, top: 0, width: 360, height: 400, background: PANEL, border: `2px solid ${right && done > 0.5 ? TEAL : LINE}`, borderRadius: 34, display: "flex", flexDirection: "column", justifyContent: "center", alignItems: "center", gap: 34 }}>
      <div style={{ fontFamily: F, fontWeight: 800, fontSize: 56, color: GRAY, letterSpacing: "0.08em" }}>{right ? "SAQUE" : "SALDO"}</div>
      {right ? (
        <div style={{ width: 130, height: 130, borderRadius: 130, background: TEAL, display: "flex", alignItems: "center", justifyContent: "center", transform: `scale(${done})` }}><IcoCheck s={84} c={WHITE} w={3} /></div>
      ) : (
        <Bar w={220} h={36} c={GOLD} />
      )}
    </div>
  );
  return (
    <>
      <Title t={t} size={130} top={280} lines={[{ w: "Mais", at: at + 0.05 }, { w: "praticidade", at: at + 0.15, hl: RED }]} />
      <div style={{ position: "absolute", left: 140, top: 720, width: 800, height: 600, transform: `translateY(${(1 - e) * 220}px)`, opacity: e }}>
        {box(false)}{box(true)}
        {[0, 1, 2].map(coin)}
        <div style={{ position: "absolute", left: 0, right: 0, top: 470, height: 30, borderRadius: 30, background: LINE, overflow: "hidden" }}>
          <div style={{ width: `${fill * 100}%`, height: "100%", background: `linear-gradient(90deg, ${DRED}, ${RED})`, borderRadius: 30 }} />
        </div>
      </div>
    </>
  );
};

