const TABS = ["Lobbies", "Hubs", "Ranking", "Camps"];
const WIN = 610; // topo da janela da plataforma (y 610–1260); o botão vem logo abaixo
const Rapida: React.FC<{ t: number; a: number }> = ({ t, a }) => {
  // o cursor troca de aba nos três adjetivos; a página nova aparece na hora
  const hits = [A.rapida, A.leve, A.otimizada];
  const tab = hits.filter((h) => t >= h).length;
  const pos = (i: number) => 22 + i * 190;
  // indicador da aba: a borda da frente anda antes da de trás (estica e assenta)
  let L = pos(0), R = pos(0) + 178;
  hits.forEach((h) => {
    L += 190 * k(t, h + 0.04, 0.38);
    R += 190 * k(t, h - 0.02, 0.26);
  });
  const pts = [{ x: 760, y: 1150 }, ...hits.map((_, i) => ({ x: 140 + pos(i + 1) + 80, y: WIN + 120 + 40 }))];
  let cur = pts[0];
  hits.forEach((h, i) => {
    const m = k(t, h - 0.42, 0.4);
    cur = { x: cur.x + (pts[i + 1].x - cur.x) * m, y: cur.y + (pts[i + 1].y - cur.y) * m };
  });
  const click = hits.reduce((s, h) => s + bump(t, h - 0.03, 0.2), 0);
  const pageAt = tab ? hits[tab - 1] : a + 0.2;
  const cards = Array.from({ length: 4 }).map((_, i) => {
    const e = k(t, pageAt + i * 0.05, 0.28);
    return (
      <div key={`${tab}-${i}`} style={{ height: 140, borderRadius: 24, background: PANEL2, border: `2px solid ${LINE}`, display: "flex", alignItems: "center", gap: 24, padding: "0 28px", transform: `translateY(${(1 - e) * 46}px)`, opacity: e }}>
        {tab % 2 ? <Avatar s={84} /> : <div style={{ width: 84, height: 84, borderRadius: 22, background: i === 0 ? RED : "#2A2E36", display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0 }}><IcoBolt s={46} c={WHITE} /></div>}
        <div style={{ display: "flex", flexDirection: "column", gap: 14 }}><Bar w={290 - i * 30} h={20} c="#3A3E47" /><Bar w={170} h={16} /></div>
        <div style={{ flex: 1 }} />
        <div style={{ width: 116, height: 56, borderRadius: 16, background: i === 0 ? RED : "#2A2E36", flexShrink: 0 }} />
      </div>
    );
  });
  const toast = pop(t, A.maisTempo, 0.4);
  return (
    <>
      <Janela top={WIN} h={650}>
        <div style={{ height: 120, display: "flex", alignItems: "center", padding: "0 36px", borderBottom: `2px solid ${LINE}` }}>
          <Img src={img("logo-rvl.png")} style={{ height: 44 }} />
          <div style={{ flex: 1 }} />
          <Avatar s={62} />
        </div>
        <div style={{ position: "relative", height: 110, borderBottom: `2px solid ${LINE}` }}>
          <div style={{ position: "absolute", left: L, width: R - L, top: 22, height: 66, borderRadius: 16, background: "rgba(255,42,63,0.16)", border: `2px solid ${RED}`, boxSizing: "border-box" }} />
          {TABS.map((w, i) => (
            <div key={w} style={{ position: "absolute", left: pos(i), width: 178, top: 22, height: 66, display: "flex", alignItems: "center", justifyContent: "center", fontFamily: F, fontWeight: 800, fontSize: 30, color: i === tab ? WHITE : GRAY, textTransform: "uppercase", letterSpacing: "0.04em" }}>{w}</div>
          ))}
        </div>
        <div style={{ height: 650 - 234, overflow: "hidden" }}>
          <div style={{ padding: 30, display: "flex", flexDirection: "column", gap: 20, transform: `translateY(${-io(t, A.otimizada + 0.5, A.maisTempo + 1.5) * 240}px)` }}>{cards}{cards.map((c, i) => <div key={`b${i}`}>{c}</div>)}</div>
        </div>
      </Janela>
      <svg width={74} height={74} viewBox="0 0 24 24" style={{ position: "absolute", left: cur.x, top: cur.y, transform: `scale(${1 - 0.15 * click})`, transformOrigin: "top left", opacity: k(t, a + 0.1, 0.3) }}>
        <path d="M4 2.5l15 8.5-6.5 1.6L9.6 19z" fill={WHITE} stroke="#000" strokeWidth={1.2} strokeLinejoin="round" />
      </svg>
      {/* menos tempo esperando, mais tempo competindo: logo abaixo da janela, y 1300–1430 */}
      <div style={{ position: "absolute", left: 140, right: 140, top: 1300, height: 130, borderRadius: 32, background: RED, display: "flex", alignItems: "center", justifyContent: "center", gap: 22, transform: `translateY(${(1 - toast) * 120}px) scale(${0.9 + 0.1 * toast})`, opacity: Math.min(1, toast * 2) }}>
        <IcoBolt s={60} c={WHITE} w={2.4} />
        <div style={{ fontFamily: F, fontWeight: 900, fontSize: 46, color: WHITE, textTransform: "uppercase", whiteSpace: "nowrap" }}>Mais tempo competindo</div>
      </div>
    </>
