// ───────── vídeo ─────────
// v3 (mais jovem): fundo com linhas diagonais finas correndo sem parar e a tela pulsando 1,2% a cada batida da trilha (140 BPM)
const BEAT = 60 / 140;
export const Fundo: React.FC<{ tv: number }> = ({ tv }) => (
  <AbsoluteFill style={{ background: `repeating-linear-gradient(115deg, transparent 0 88px, rgba(255,255,255,0.035) 88px 91px)`, backgroundSize: "200% 200%", backgroundPosition: `${(tv * 60) % 1000}px 0px` }} />
);
export const Rival: React.FC = () => {
  const frame = useCurrentFrame();
  const t = frame / RV_FPS - LEAD;
  const tv = frame / RV_FPS;
  const ph = (tv % BEAT) / BEAT;
  const pulse = tv > 0.4 ? Math.exp(-ph * 9) : 0;
  return (
    <AbsoluteFill style={{ background: BG, fontFamily: F, overflow: "hidden" }}>
      <Fundo tv={tv} />
      <AbsoluteFill style={{ transform: `scale(${1 + 0.012 * pulse})` }}>
      <Scene t={t} a={-LEAD} b={A.conheca} cam="push"><Cena1 t={t} /></Scene>
      <Scene t={t} a={A.conheca} b={A.taxaSaque - 0.35} cam="pull" exit="zoom"><LogoAbre t={t} /></Scene>
      <Scene t={t} a={A.taxaSaque - 0.35} b={A.assinatura - 0.1} cam="tilt" enter="zoom"><Cena2 t={t} /></Scene>
      <Scene t={t} a={A.assinatura - 0.1} b={A.alem - 0.1} cam="panR"><Cena3 t={t} /></Scene>
      <Scene t={t} a={A.alem - 0.1} b={A.eNada - 0.1} cam="push" exit="up"><Cena4 t={t} /></Scene>
      <Scene t={t} a={A.eNada - 0.1} b={A.semRegras - 0.1} cam="rot" enter="up"><Cena5 t={t} /></Scene>
      <Scene t={t} a={A.semRegras - 0.1} b={A.jogue - 0.1} cam="pull" exit="left"><Cena6 t={t} /></Scene>
      <Scene t={t} a={A.jogue - 0.1} b={A.eTudo - 0.1} cam="panL" enter="left" exit="zoom"><Cena7 t={t} /></Scene>
      <Scene t={t} a={A.eTudo - 0.1} b={A.menosTaxas - 0.08} cam="push" enter="zoom"><Cena8 t={t} /></Scene>
      <Scene t={t} a={A.menosTaxas - 0.08} b={DUR + 1} cam="pull"><Cena9 t={t} /></Scene>
      </AbsoluteFill>
      {/* trocas: lâmina, mergulho, inundação, empurrão — nunca a mesma duas vezes seguidas */}
      <Slash t={t} at={A.conheca} dir={1} />
      <Slash t={t} at={A.assinatura - 0.1} dir={-1} />
      <Flood t={t} at={A.alem - 0.1} x={540} y={680} c={GOLD} />
      <Slash t={t} at={A.aRival} dir={1} />
      <Flood t={t} at={A.semRegras - 0.1} x={540} y={1360} c={DRED} />
    </AbsoluteFill>
  );
};

import { loadFont } from "@remotion/google-fonts/Saira";
import React from "react";
import { AbsoluteFill, Easing, Img, OffthreadVideo, Sequence, interpolate, staticFile, useCurrentFrame } from "remotion";
import { A, DUR, LEAD } from "./temposV5";

// RIVAL (cliente caio rivalx) — v5: as funcionalidades da plataforma, com as telas reais do site (sandbox, Modo Amostra).
// Jeito: vitrine. A tela do site fica numa janela grande (câmera estilo Screen Studio: rola, aproxima, toca), o letreiro
// fica parado em cima, e a mesma tela desfocada preenche o fundo. Identidade igual às versões anteriores (preto, branco,
// vermelho #FF2A3F, dourado, teal; Saira pesada; lâmina vermelha nas viradas). Voz Mário (src/voz-v5.wav).
// Só entra o que está no site: nenhum número de taxa, prazo ou preço.
// Coordenadas das telas: espaço de 800 x 1422 (o print do celular); as imagens em public/ têm o dobro.

const { fontFamily: F } = loadFont("normal", { weights: ["600", "700", "800", "900"], subsets: ["latin", "latin-ext"] });

export const V5_FPS = 30;
export const V5_FRAMES = Math.round(DUR * V5_FPS);

const cl = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;
const OUT = Easing.bezier(0.16, 1, 0.3, 1);
const INOUT = Easing.bezier(0.65, 0, 0.35, 1);
const IN = Easing.bezier(0.55, 0, 1, 0.45);
const BACK = Easing.out(Easing.back(1.4));
const k = (t: number, a: number, d = 0.45) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: OUT });
const pop = (t: number, a: number, d = 0.4) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: BACK });
const lin = (t: number, a: number, b: number) => interpolate(t, [a, b], [0, 1], cl);
const io = (t: number, a: number, b: number) => interpolate(t, [a, b], [0, 1], { ...cl, easing: INOUT });
const acc = (t: number, a: number, b: number) => interpolate(t, [a, b], [0, 1], { ...cl, easing: IN });

const BG = "#07080A";
const WHITE = "#F4F4F5";
const RED = "#FF2A3F";
const DRED = "#991926";
const TEAL = "#009982";
const GOLD = "#DCB859";
const img = (f: string) => staticFile(`caio-rivalx/${f}`);
const tela = (f: string) => staticFile(`caio-rivalx/site/${f}.jpg`);

// ───────── letreiro: entra por máscara e fica parado; o anterior some inteiro antes do próximo ─────────
type Ln = { w: string; hl?: string; at?: number };
export type Tit = { at: number; lines: Ln[] };
const MAXW = 800;
const fit = (w: string, size: number, hl?: boolean) => Math.min(size, Math.floor(MAXW / (0.66 * w.length + (hl ? 0.7 : 0))));

const Linha: React.FC<{ t: number; at: number; out?: number; ln: Ln; size: number }> = ({ t, at, out, ln, size }) => {
  const e = k(t, at, 0.38);
  const o = out === undefined ? 0 : lin(t, out, out + 0.12);
  const fs = fit(ln.w, size, !!ln.hl);
  const band = k(t, at + 0.08, 0.32);
  return (
    <div style={{ overflow: "hidden", padding: "0.05em 0.4em", marginTop: "-0.02em" }}>
      <div style={{ transform: `translateY(${((1 - e) * 112).toFixed(2)}%)`, opacity: (t >= at ? 1 : 0) * (1 - o), position: "relative", fontFamily: F, fontWeight: 900, fontSize: fs, lineHeight: 1.12, textTransform: "uppercase", whiteSpace: "nowrap", letterSpacing: "-0.005em", color: ln.hl === GOLD ? BG : WHITE }}>
        {ln.hl && <div style={{ position: "absolute", left: "-0.2em", right: "-0.2em", top: "7%", bottom: "5%", background: ln.hl, transform: `skewX(-9deg) scaleX(${band.toFixed(4)})`, transformOrigin: "left center" }} />}
        <span style={{ position: "relative" }}>{ln.w}</span>
      </div>
    </div>
  );
};

const Letreiro: React.FC<{ t: number; tits: Tit[]; end: number; top?: number; size?: number; h?: number }> = ({ t, tits, end, top = 240, size = 116, h = 280 }) => (
  <>
    {tits.map((ti, i) => {
      const out = (tits[i + 1]?.at ?? end) - 0.14;
      if (t < ti.at - 0.05 || t > out + 0.14) return null;
      return (
        <div key={i} style={{ position: "absolute", left: 100, right: 100, top, height: h, display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center" }}>
          {ti.lines.map((ln, j) => <Linha key={j} t={t} at={ln.at ?? ti.at + j * 0.08} out={out} ln={ln} size={size} />)}
        </div>
      );
    })}
  </>
);

// ───────── janela com a tela do site: câmera, toques e marcações ─────────
const WX = 120, WY = 560, WW = 840, WH = 1000, IW = 800, IH = 1422;
type KF = [number, number, number, number]; // tempo, centro x, centro y, zoom (1,05 = largura inteira)
type Mark = { kind: "box" | "tap"; x: number; y: number; w?: number; h?: number; at: number; out?: number; c?: string };
export type Shot = { src: string; at: number; kf: KF[]; enter?: "up" | "right" | "zoom"; marks?: Mark[] };

const cam = (t: number, kf: KF[]) => {
  let v: number[] = [kf[0][1], kf[0][2], kf[0][3]];
  for (let i = 0; i < kf.length - 1; i++) {
    const [a, b] = [kf[i], kf[i + 1]];
    if (t >= a[0]) {
      const p = io(t, a[0], b[0]);
      v = [a[1] + (b[1] - a[1]) * p, a[2] + (b[2] - a[2]) * p, a[3] + (b[3] - a[3]) * p];
    }
  }
  const [cx, cy, s] = v;
  const hw = WW / 2 / s, hh = WH / 2 / s;
  return { s, cx: hw >= IW / 2 ? IW / 2 : Math.min(IW - hw, Math.max(hw, cx)), cy: Math.min(IH - hh, Math.max(hh, cy)) };
};

const Marca: React.FC<{ t: number; m: Mark }> = ({ t, m }) => {
  const c = m.c ?? RED;
  if (m.kind === "box") {
    if (t < m.at) return null;
    const e = k(t, m.at, 0.35), o = m.out === undefined ? 0 : lin(t, m.out, m.out + 0.15);
    return <div style={{ position: "absolute", left: m.x, top: m.y, width: m.w, height: m.h, border: `4px solid ${c}`, borderRadius: 12, background: `${c}1F`, boxShadow: `0 0 26px ${c}99`, opacity: e * (1 - o), transform: `scale(${(1.14 - 0.14 * e).toFixed(4)})` }} />;
  }
  // toque: o dedo chega, aperta e solta um anel discreto
  const vis = lin(t, m.at - 0.4, m.at - 0.25) * (1 - lin(t, m.at + 0.45, m.at + 0.6));
  if (vis <= 0) return null;
  const mv = 1 - k(t, m.at - 0.4, 0.38);
  const press = 1 - 0.28 * (lin(t, m.at - 0.04, m.at + 0.03) - lin(t, m.at + 0.08, m.at + 0.22));
  const ring = lin(t, m.at, m.at + 0.45);
  return (
    <>
      {ring > 0 && ring < 1 && <div style={{ position: "absolute", left: m.x - 60, top: m.y - 60, width: 120, height: 120, borderRadius: 60, border: `5px solid ${WHITE}`, opacity: 1 - ring, transform: `scale(${(0.25 + 0.75 * OUT(ring)).toFixed(4)})` }} />}
      <div style={{ position: "absolute", left: m.x - 24 + mv * 90, top: m.y - 24 + mv * 120, width: 48, height: 48, borderRadius: 24, background: "rgba(244,244,245,0.92)", border: "3px solid rgba(0,0,0,0.35)", boxShadow: "0 6px 18px rgba(0,0,0,0.5)", opacity: vis, transform: `scale(${press.toFixed(4)})` }} />
    </>
  );
};

const Janela: React.FC<{ t: number; a: number; b: number; shots: Shot[] }> = ({ t, a, b, shots }) => {
  const en = k(t, a, 0.5), ex = acc(t, b - 0.16, b);
  return (
    <div style={{ position: "absolute", left: WX, top: WY, width: WW, height: WH, borderRadius: 40, overflow: "hidden", background: "#050506", border: "2px solid rgba(255,255,255,0.14)", boxShadow: `0 0 0 6px rgba(255,42,63,0.16), 0 40px 110px rgba(255,42,63,0.22)`, transform: `translateY(${((1 - en) * 150).toFixed(1)}px) scale(${(0.93 + 0.07 * en + 0.04 * ex).toFixed(4)})`, opacity: Math.min(1, en * 1.6) * (1 - ex) }}>
      {shots.map((sh, i) => {
        const fim = shots[i + 1] ? shots[i + 1].at + 0.42 : b + 0.2;
        if (t < sh.at - 0.02 && i > 0) return null;
        if (t > fim) return null;
        const c = cam(t, sh.kf);
        const e = i === 0 ? 1 : k(t, sh.at, 0.4);
        const tr = sh.enter === "right" ? `translateX(${((1 - e) * WW).toFixed(1)}px)` : sh.enter === "zoom" ? `scale(${(1.18 - 0.18 * e).toFixed(4)})` : `translateY(${((1 - e) * WH).toFixed(1)}px)`;
        return (
          <div key={i} style={{ position: "absolute", inset: 0, overflow: "hidden", background: "#050506", transform: tr, opacity: sh.enter === "zoom" ? Math.min(1, e * 2) : 1 }}>
            <div style={{ position: "absolute", left: 0, top: 0, width: IW, height: IH, transformOrigin: "0 0", transform: `translate(${(WW / 2 - c.cx * c.s).toFixed(2)}px, ${(WH / 2 - c.cy * c.s).toFixed(2)}px) scale(${c.s.toFixed(4)})` }}>
              <Img src={tela(sh.src)} style={{ width: IW, height: IH, display: "block" }} />
              {sh.marks?.map((m, j) => <Marca key={j} t={t} m={m} />)}
            </div>
          </div>
        );
      })}
    </div>
  );
};

// a mesma tela, desfocada e escura, preenche o quadro atrás da janela (sem área vazia)
const Atras: React.FC<{ t: number; a: number; b: number; src: string }> = ({ t, a, b, src }) => (
  <AbsoluteFill style={{ opacity: 0.85 * k(t, a, 0.5) * (1 - lin(t, b - 0.15, b)) }}>
    <Img src={tela(src)} style={{ width: 1080, height: 1920, objectFit: "cover", filter: "blur(40px) brightness(0.8) saturate(1.5)", transform: `scale(${(1.25 + 0.06 * lin(t, a, b)).toFixed(4)})` }} />
  </AbsoluteFill>
);

// logo do cliente no rodapé (fora da área segura de texto: só preenche o quadro)
const Rodape: React.FC = () => <Img src={img("logo-rivalx.png")} style={{ position: "absolute", left: 390, top: 1640, width: 300, opacity: 0.85 }} />;

export const Cena: React.FC<{ t: number; a: number; b: number; shots: Shot[]; tits: Tit[]; size?: number }> = ({ t, a, b, shots, tits, size }) => {
  if (t < a || t >= b) return null;
  return (
    <>
      <Atras t={t} a={a} b={b} src={shots[0].src} />
      <Janela t={t} a={a} b={b} shots={shots} />
      <Letreiro t={t} tits={tits} end={b} size={size} />
      <Rodape />
    </>
  );
};

// ───────── abertura e final: o jogo escurecido atrás do logo (como na v4) ─────────
const Jogo: React.FC<{ src: string; from: number; esc: number; t: number; a: number }> = ({ src, from, esc, t, a }) => (
  <AbsoluteFill style={{ background: "#000" }}>
    <AbsoluteFill style={{ transform: `scale(${1.04 + 0.06 * lin(t, a, a + 8)})` }}>
      <Sequence from={from} layout="none">
        <OffthreadVideo src={img(src)} muted style={{ width: 1080, height: 1920, objectFit: "cover" }} />
      </Sequence>
    </AbsoluteFill>
    <AbsoluteFill style={{ background: `rgba(0,0,0,${esc})` }} />
  </AbsoluteFill>
);

const Abre: React.FC<{ t: number; b: number }> = ({ t, b }) => {
  if (t >= b) return null;
  return (
    <>
      <Jogo src="jogo-logo.mp4" from={0} esc={0.55} t={t} a={-LEAD} />
      <AbsoluteFill style={{ transform: `translateY(-330px) scale(${0.96 + 0.04 * lin(t, -LEAD, b)})`, mixBlendMode: "screen" }}>
        <Sequence from={0} layout="none">
          <OffthreadVideo src={img("logo-anim-9x16.mp4")} muted style={{ width: 1080, height: 1920 }} />
        </Sequence>
      </AbsoluteFill>
      <Letreiro t={t} end={b + 1} top={830} h={460} size={128} tits={[{ at: A.sua, lines: [{ w: "Sua próxima", at: A.sua + 0.25 }, { w: "partida", at: A.sua + 0.7 }, { w: "começa aqui.", at: A.comeca, hl: RED }] }]} />
    </>
  );
};

const Fim: React.FC<{ t: number; a: number }> = ({ t, a }) => {
  if (t < a) return null;
  const tag = A.prepare - 0.1;
  const sw = lin(t, a + 0.5, a + 1.5);
  return (
    <>
      <AbsoluteFill style={{ background: "#000" }} />
      <AbsoluteFill style={{ opacity: io(t, a, a + 0.6) }}>
        <Jogo src="jogo-final.mp4" from={Math.round((a + LEAD) * V5_FPS)} esc={0.7} t={t} a={a} />
      </AbsoluteFill>
      <div style={{ position: "absolute", left: 170, top: 560, width: 740, opacity: k(t, a + 0.05, 0.4), transform: `scale(${((0.86 + 0.14 * pop(t, a + 0.05, 0.5)) * (1 + 0.04 * lin(t, a + 0.6, a + 5.5))).toFixed(4)})` }}>
        <div style={{ position: "relative", width: 740, height: 146 }}>
          <Img src={img("logo-rivalx.png")} style={{ width: 740, position: "absolute", inset: 0 }} />
          <div style={{ position: "absolute", inset: 0, WebkitMaskImage: `url(${img("logo-rivalx.png")})`, WebkitMaskSize: "100% 100%", maskImage: `url(${img("logo-rivalx.png")})`, maskSize: "100% 100%", background: `linear-gradient(105deg, transparent ${-30 + 160 * sw}%, ${RED} ${-15 + 160 * sw}%, transparent ${0 + 160 * sw}%)` }} />
        </div>
      </div>
      <Letreiro t={t} end={DUR + 5} top={850} h={460} size={128} tits={[{ at: tag, lines: [{ w: "Prepare-se", at: tag + 0.1 }, { w: "para o", at: tag + 0.5 }, { w: "lançamento", at: A.lancamento - 0.1, hl: RED }] }]} />
    </>
  );
};

// ───────── 5 contra 5: o vermelho inunda a tela, o número bate e encolhe para a cena seguinte ─────────
const CincoV5: React.FC<{ t: number; a: number; b: number }> = ({ t, a, b }) => {
  if (t < a - 0.25 || t > b + 0.3) return null;
  const r = 1500 * (k(t, a - 0.25, 0.4) - acc(t, b - 0.05, b + 0.3));
  const e = pop(t, a, 0.4);
  return (
    <AbsoluteFill style={{ background: RED, clipPath: `circle(${Math.max(0, r).toFixed(1)}px at 540px 1020px)` }}>
      <div style={{ position: "absolute", left: -500 + 2200 * lin(t, a, a + 1.3), top: -400, width: 240, height: 2800, background: "rgba(0,0,0,0.12)", transform: "rotate(22deg)" }} />
      <div style={{ position: "absolute", left: 100, right: 100, top: 600, display: "flex", flexDirection: "column", alignItems: "center", transform: `scale(${((0.6 + 0.4 * e) * (1 + 0.04 * lin(t, a + 0.3, b))).toFixed(4)})`, opacity: Math.min(1, e * 2) }}>
        <div style={{ display: "flex", alignItems: "baseline", gap: 26, fontFamily: F, fontWeight: 900, color: WHITE, lineHeight: 1 }}>
          <span style={{ fontSize: 400 }}>5</span><span style={{ fontSize: 190, color: BG }}>V</span><span style={{ fontSize: 400 }}>5</span>
        </div>
        <div style={{ marginTop: 24, fontFamily: F, fontWeight: 900, fontSize: 78, color: BG, textTransform: "uppercase", whiteSpace: "nowrap" }}>Cinco contra cinco</div>
      </div>
    </AbsoluteFill>
  );
};

// ───────── tudo sem sair da plataforma: as quatro telas juntas ─────────
export const Mosaico: React.FC<{ t: number; a: number; b: number; itens: [string, string][]; linhas: [string, string] }> = ({ t, a, b, itens, linhas }) => {
  if (t < a || t >= b) return null;
  const ex = acc(t, b - 0.16, b);
  return (
    <>
      <Atras t={t} a={a} b={b} src={itens[0][0]} />
      <div style={{ position: "absolute", left: WX, top: WY, width: WW, height: WH, opacity: 1 - ex, transform: `scale(${(1 + 0.04 * ex).toFixed(4)})` }}>
        {itens.map(([src, nome], i) => {
          const e = pop(t, a + 0.05 + i * 0.09, 0.42);
          const x = (i % 2) * 430, y = Math.floor(i / 2) * 510;
          return (
            <div key={i} style={{ position: "absolute", left: x, top: y, width: 410, height: 490, borderRadius: 30, overflow: "hidden", background: "#050506", border: "2px solid rgba(255,255,255,0.16)", boxShadow: "0 24px 60px rgba(0,0,0,0.6)", transform: `scale(${(0.6 + 0.4 * e).toFixed(4)}) rotate(${((1 - e) * (i % 2 ? 6 : -6)).toFixed(2)}deg)`, opacity: Math.min(1, e * 2) }}>
              <Img src={tela(src)} style={{ position: "absolute", left: 0, top: src === "chat-1-conversas" ? 0 : -70 - 30 * lin(t, a, b), width: 410 }} />
              <div style={{ position: "absolute", left: 0, right: 0, bottom: 0, height: 150, background: "linear-gradient(transparent, rgba(0,0,0,0.92))" }} />
              <div style={{ position: "absolute", left: 22, bottom: 20, padding: "4px 18px", background: RED, transform: "skewX(-9deg)" }}>
                <div style={{ fontFamily: F, fontWeight: 900, fontSize: 40, color: WHITE, textTransform: "uppercase", transform: "skewX(9deg)", whiteSpace: "nowrap" }}>{nome}</div>
              </div>
            </div>
          );
        })}
      </div>
      <Letreiro t={t} end={b} tits={[{ at: a + 0.05, lines: [{ w: linhas[0] }, { w: linhas[1], hl: RED }] }]} />
      <Rodape />
    </>
  );
};

// ───────── viradas ─────────
const Lamina: React.FC<{ t: number; at: number; dir: 1 | -1 }> = ({ t, at, dir }) => {
  const p = lin(t, at - 0.2, at + 0.24);
  if (p <= 0 || p >= 1) return null;
  const x = dir === 1 ? -900 + 2500 * p : 1500 - 2500 * p;
  return <div style={{ position: "absolute", left: x, top: -500, width: 520, height: 3000, background: RED, transform: `rotate(${dir * 20}deg)`, boxShadow: `0 0 80px ${RED}` }} />;
};
const Inunda: React.FC<{ t: number; at: number; x: number; y: number; c: string }> = ({ t, at, x, y, c }) => {
  if (t < at - 0.26 || t > at + 0.34) return null;
  const r = 2300 * acc(t, at - 0.26, at);
  const o = 1 - k(t, at + 0.02, 0.3);
  return <AbsoluteFill style={{ background: c, clipPath: `circle(${r.toFixed(1)}px at ${x}px ${y}px)`, opacity: o }} />;
};

const BEAT = 60 / 140;
const Fundo: React.FC<{ tv: number }> = ({ tv }) => (
  <AbsoluteFill style={{ background: `repeating-linear-gradient(115deg, transparent 0 88px, rgba(255,255,255,0.035) 88px 91px)`, backgroundSize: "200% 200%", backgroundPosition: `${(tv * 60) % 1000}px 0px` }} />
);

export const RivalV5: React.FC = () => {
  const frame = useCurrentFrame();
  const t = frame / V5_FPS - LEAD;
  const tv = frame / V5_FPS;
  const ph = (tv % BEAT) / BEAT;
  const pulse = tv > 0.4 ? Math.exp(-ph * 9) : 0;
  // cortes entre as cenas (0,1 s antes da palavra que abre cada uma)
  const c1 = A.noHub - 0.1, c2 = A.tem - 0.1, c3 = A.dentro - 0.1, c4 = A.cadaSala - 0.1, c5 = A.carteira - 0.1, c6 = A.toda - 0.1;
  const c7 = A.torneios - 0.1, c8 = A.monte - 0.1, c9 = A.tudo - 0.1, c10 = A.jogue - 0.2, c11 = A.club - 0.1, c12 = A.fim - 0.1;
  return (
    <AbsoluteFill style={{ background: BG, fontFamily: F, overflow: "hidden" }}>
      <Fundo tv={tv} />
      <AbsoluteFill style={{ transform: `scale(${1 + 0.012 * pulse})` }}>
        <Abre t={t} b={c1} />

        {/* hub: lobbys abertos, quem está online, entrar com um clique */}
        <Cena t={t} a={c1} b={c2}
          shots={[{ src: "hub-1-topo", at: c1, kf: [[c1, 400, 438, 1.05], [A.lobbies - 0.2, 400, 438, 1.05], [A.quem - 0.3, 400, 760, 1.05], [A.quem + 0.25, 280, 1085, 1.55], [A.entra - 0.15, 280, 1085, 1.55], [A.entra + 0.35, 290, 950, 1.5]],
            marks: [{ kind: "box", x: 70, y: 1030, w: 410, h: 100, at: A.quem + 0.2, out: A.entra - 0.2, c: TEAL }, { kind: "tap", x: 280, y: 950, at: A.clique - 0.05 }] }]}
          tits={[{ at: c1 + 0.1, lines: [{ w: "No hub," }, { w: "lobbys abertos", hl: RED }] }, { at: A.quem, lines: [{ w: "Quem está" }, { w: "online", hl: TEAL }] }, { at: A.entra, lines: [{ w: "Entre com" }, { w: "um clique", hl: RED }] }]} />

        {/* filas por elo */}
